// lib/sacred-categories.ts — Central source of truth for all sacred temple categories
// All pages, forms, and APIs must import from this single file.

export type SacredCategory = {
  slug: string
  name: string          // stored in MongoDB categories/sacredCategories — backward compatible
  nameHi: string
  description: string   // short desc for cards
  longDescription: string // longer desc for pilgrimage pages
  deity: string         // deity tag for UI badge
  icon: string
  group: string         // group key for grouping in UI
  order: number
  isActive: boolean
  relatedSlugs: string[]
}

export type CategoryGroup = {
  key: string
  label: string
  labelHi: string
  order: number
}

