// ─── Indexes & Helpers ───────────────────────────────────────────────────────

const _bySlug = new Map<string, SacredCategory>()
const _byName = new Map<string, SacredCategory>()
for (const cat of SACRED_CATEGORIES) {
  _bySlug.set(cat.slug, cat)
  _byName.set(cat.name.toLowerCase(), cat)
}

// Backward-compatible slug aliases
_bySlug.set('shakti-peethas', _bySlug.get('shakti-peeth')!)
_bySlug.set('51-shakti-peethas', _bySlug.get('shakti-peeth')!)
_bySlug.set('52-shakti-peethas', _bySlug.get('shakti-peeth')!)

export function getCategoryBySlug(slug: string): SacredCategory | undefined {
  return _bySlug.get(slug)
}

export function getCategoryByName(name: string): SacredCategory | undefined {
  return _byName.get(name.toLowerCase())
}

export function getSlugForCategoryName(name: string): string {
  return getCategoryByName(name)?.slug || name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

export function getCategoryNameForSlug(slug: string): string {
  return getCategoryBySlug(slug)?.name || slug
}

export function getAllCategoryNames(): string[] {
  return SACRED_CATEGORIES.filter(c => c.isActive).map(c => c.name)
}

export function getAllCategorySlugs(): string[] {
  return SACRED_CATEGORIES.filter(c => c.isActive).map(c => c.slug)
}

export function getCategoriesByGroup(groupKey: string): SacredCategory[] {
  return SACRED_CATEGORIES.filter(c => c.group === groupKey && c.isActive).sort((a, b) => a.order - b.order)
}

export function getGroupedCategories(): { group: CategoryGroup; categories: SacredCategory[] }[] {
  return CATEGORY_GROUPS.map(group => ({
    group,
    categories: getCategoriesByGroup(group.key),
  })).filter(g => g.categories.length > 0)
}
